import * as React from "react";
import { MenuBlock } from "../../menuBlock";
import type { MenuBlockProps } from "../../menuBlock";
import { SvgMpaIcon } from "../../../assets/icons";
import { IconButton } from "../../iconButton";
import { Button } from "../../button";
import "./TruncatedMenu.scss";
import Separator from "../Separator/Separator";
import clsx from "clsx";

export interface TruncatedMenuProps {
  hoverStyle?: "normal" | "underline";
  colour?: "link" | "black" | "white";
  icon?: keyof typeof SvgMpaIcon;
  label?: string;
  separator?: React.ReactNode;
  menuItems: MenuBlockProps["menuItems"];
}

const TruncatedMenu = ({
  hoverStyle,
  colour,
  icon = "ThreeDots_SGDS",
  label,
  separator,
  menuItems,
}: TruncatedMenuProps) => {
  const [menuOpen, setMenuOpen] = React.useState(false);

  const handleClick = () => {
    setMenuOpen((v) => !v);
  };
  const getButton = () => {
    if (label) {
      return (
        <Button
          id="breadcrumb-truncated-icon-button"
          className={clsx("breadcrumb-truncated-icon-button", {
            "truncated-icon-button-black": colour === "black",
          })}
          trailingIcon="CaretDown_Filled"
          btnType="text"
          onClick={handleClick}
          label={label}
        >        
        </Button>
      );
    }
    return (
      <IconButton
        id="breadcrumb-truncated-icon-button"
        className={clsx(
          "breadcrumb-truncated-icon-button", {
          "truncated-icon-button-black": colour === "black",
          "truncated-icon-button-white": colour === "white",
          },
          hoverStyle
        )}
        icon={icon}
        btnType="standard"
        onClick={handleClick}
      />
    );
  };

  return (
    <div className="breadcrumb-truncated-base">
      <div className="breadcrumb-truncated-button-block">
        {getButton()}
        {menuOpen && (
          <div className="breadcrumb-truncated-menu">
            <MenuBlock id={"menuBlockId"} menuItems={menuItems} />
          </div>
        )}
      </div>
      <Separator colour={colour} separator={separator} />
    </div>
  );
};

export default TruncatedMenu;
